"use strict";(self.webpackChunkstudy_notes=self.webpackChunkstudy_notes||[]).push([[4736],{6123:(a,e,n)=>{n.r(e),n.d(e,{comp:()=>l,data:()=>r});var s=n(9588);const i={},l=(0,n(5726).A)(i,[["render",function(a,e){return(0,s.uX)(),(0,s.CE)("div",null,[...e[0]||(e[0]=[(0,s.Fv)('<h1 id="传感器" tabindex="-1"><a class="header-anchor" href="#传感器"><span>传感器</span></a></h1><h2 id="编码器" tabindex="-1"><a class="header-anchor" href="#编码器"><span>编码器</span></a></h2><h3 id="编码器分类" tabindex="-1"><a class="header-anchor" href="#编码器分类"><span>编码器分类</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">编码器分类</span>\n<span class="line">├── 检测原理</span>\n<span class="line">│   ├── 光电式</span>\n<span class="line">│   └── 磁电式</span>\n<span class="line">└── 编码类型</span>\n<span class="line">    ├── 绝对式</span>\n<span class="line">    └── 增量式</span>\n<span class="line"></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="编码器基本参数" tabindex="-1"><a class="header-anchor" href="#编码器基本参数"><span>编码器基本参数</span></a></h3><ul><li>分辨率：指编码器能够分辨的最小单位。对于增量式编码器，其分辨率表示为编码器转轴旋转一圈所产生的脉冲数，也叫多少线，较为常见的有 5-6000 线。对于绝对式编码器，内部码盘所用的位数就是它的分辨率，单位是位 (bit)，具体还分单圈分辨率和多圈分辨率。</li><li>精度：编码器每个读数与转轴实际位置间的最大误差，通常用角度、角分或角秒来表示。</li><li>最大响应频率：指编码器每秒输出的脉冲数，单位是 Hz，也称为 PPS。计算公式：最大响应频率 = 分辨率 * 轴转速/60。</li><li>信号输出形式：对于增量式编码器，每个通道的信号独立输出。对于绝对式编码器，由于是直接输出几十位的二进制数，为了确保传输速率和信号质量，一般采用串行输出或总线型输出。</li><li>最大转速：指编码器机械系统所能承受的最高转速。</li></ul><h3 id="编码器工作原理" tabindex="-1"><a class="header-anchor" href="#编码器工作原理"><span>编码器工作原理</span></a></h3><h3 id="参考文档" tabindex="-1"><a class="header-anchor" href="#参考文档"><span>参考文档</span></a></h3><p><a href="https://blog.csdn.net/weixin_44567668/article/details/133784168" target="_blank" rel="noopener noreferrer">电机编码器</a></p>',9)])])}]]),r=JSON.parse('{"path":"/Embeded/10_Motor/02_Sensor.html","title":"传感器","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1762739221000,"contributors":[{"name":"PC-20250430KOXD\\\\Administrator","username":"","email":"mlh18@qq.com","commits":1}],"changelog":[{"hash":"87a22624b94cdf151bfeb3d6427d18649a3db324","time":1762739221000,"email":"mlh18@qq.com","author":"PC-20250430KOXD\\\\Administrator","message":"新增传感器和编码器相关文档，更新FOC文档中的图片路径并添加新图片"}]},"filePathRelative":"Embeded/10_Motor/02_Sensor.md"}')}}]);